// list (messages.json), in Modern Standard Arabic with the words Microsoft
// Office uses in Arabic, a counted message in all six of Arabic's plural
// forms. The words for the suite's recurring terms are in GLOSSARY-ar.md
// beside this file, which a change of a word here follows. Drafted by
// machine and checked against the list by tests/catalogues.test.js; a
// native speaker's review is still to come.

