  'Add an account to fetch mail, or import what you already have — an Outlook .pst or .ost, an mbox, or a folder of messages. Rutba Office can find them for you.': 'أضف حسابًا لجلب البريد، أو استورد ما لديك بالفعل — ملف Outlook بتنسيق .pst أو .ost، أو ملف mbox، أو مجلد رسائل. يمكن لـ Rutba Office العثور عليها نيابةً عنك.',
