  'Each account keeps its own options, as in Outlook.': 'يحتفظ كل حساب بخياراته الخاصة، كما في Outlook.',
  'Each category is written as Word\'s TOA field, its heading over it; All writes one for every category that has citations in it.': 'تُكتب كل فئة كحقل TOA الخاص بـ Word وعنوانها فوقه؛ ويكتب «الكل» حقلاً لكل فئة تحتوي على اقتباسات.',
  'Each cell its own paragraph': 'كل خلية في فقرة مستقلة',
  'Each is set up as Add account does: a provider in the built-in list straight away; for any other domain, its own records are looked up when you press Add (its DNS, autoconfig and autodiscover addresses), and nothing else is asked.': 'يُعدّ كل حساب كما تفعل إضافة حساب: المزوّد الموجود في القائمة المضمّنة فورًا؛ وأي نطاق آخر تُستعلم سجلاته الخاصة فقط عند الضغط على إضافة (نظام DNS الخاص به وعناوين autoconfig وautodiscover)، ولا يُسأل أي طرف آخر.',
  'Each line is a paragraph of its own. Ctrl+Enter puts the words in.': 'كل سطر فقرة مستقلة. اضغط Ctrl+Enter لإدراج النص.',
  'Each message is the merged letter itself. The account\'s signature is not added: what you wrote in the letter is what each person receives.': 'كل رسالة هي الخطاب المدمج نفسه. لا يُضاف توقيع الحساب: ما كتبته في الخطاب هو ما يتلقاه كل شخص.',
  'Each numbered level shows its own number: keep %{level} in level {level}\'s number.': 'يُظهر كل مستوى مرقّم رقمه الخاص: أبقِ %{level} في رقم المستوى {level}.',
  'Each page is written as a picture into a folder you choose: {count} in all. This document is not changed.': 'تُكتب كل صفحة صورةً في مجلد تختاره: {count} في المجموع. لا يتغير هذا المستند.',
  'Each sender hears from this once while it stays on — a second message from the same person is not answered again until it is turned off and on. A mailing list, a no-reply address and a message that already says it is automatic are never answered.': 'يتلقى كل مرسِل هذا الرد مرة واحدة ما دام قيد التشغيل — فلا يُرد على رسالة ثانية من الشخص نفسه حتى يتم إيقاف تشغيله ثم تشغيله من جديد. ولا يُرد أبداً على قائمة بريدية أو عنوان لا يقبل الردود (no-reply) أو رسالة تذكر أنها تلقائية.',
  'Each slide then moves on by itself after the time it was on screen, and Use Timings is turned on.': 'بعد ذلك تنتقل كل شريحة تلقائياً بعد المدة التي ظهرت فيها على الشاشة، ويتم تشغيل «استخدام التوقيتات».',
  'Each ticked field gets a panel of buttons, one per item, that filters the pivot table.': 'يحصل كل حقل محدد على لوحة أزرار، زر لكل عنصر، تقوم بتصفية جدول PivotTable.',
  'Each ticked field gets a panel of buttons, one per item, that filters the table.': 'يحصل كل حقل محدد على لوحة أزرار، زر لكل عنصر، تقوم بتصفية الجدول.',
