  'Show Changes — {count} slide different since this deck was last open here': { zero: 'إظهار التغييرات — لا توجد شرائح مختلفة منذ آخر مرة فُتح فيها هذا العرض التقديمي هنا', one: 'إظهار التغييرات — شريحة واحدة مختلفة منذ آخر مرة فُتح فيها هذا العرض التقديمي هنا', two: 'إظهار التغييرات — شريحتان مختلفتان منذ آخر مرة فُتح فيها هذا العرض التقديمي هنا', few: 'إظهار التغييرات — {count} شرائح مختلفة منذ آخر مرة فُتح فيها هذا العرض التقديمي هنا', many: 'إظهار التغييرات — {count} شريحة مختلفة منذ آخر مرة فُتح فيها هذا العرض التقديمي هنا', other: 'إظهار التغييرات — {count} شريحة مختلفة منذ آخر مرة فُتح فيها هذا العرض التقديمي هنا' },
  'Show Comments': 'إظهار التعليقات',
  'Show Comments — every comment thread in the workbook in a pane, open or resolved': 'إظهار التعليقات — كل سلاسل التعليقات في المصنف ضمن جزء، المفتوحة منها والمحلولة',
