  'Signature: your signature, typed, drawn or from a picture, placed where you click; not a digital signature': 'التوقيع: توقيعك، مكتوبًا أو مرسومًا أو من صورة، يوضع حيث تنقر؛ ليس توقيعًا رقميًا',
  'Signed by': 'الموقِّع',
  'Signed by {name} with a certificate that is not meant for mail.': 'وقّعها {name} بشهادة غير مخصصة للبريد.',
  'Signed by {name}, and the message has not changed, but no authority this computer trusts vouches for the certificate.': 'موقَّعة من {name} ولم تتغير الرسالة، لكن لا توجد جهة يثق بها هذا الحاسوب تضمن الشهادة.',
  'Signed by {name}, and the message has not changed, but the certificate is out of date.': 'موقّعة من {name}، ولم تتغير الرسالة، لكن الشهادة منتهية الصلاحية.',
  'Signed by {name}, but the message has changed since it was signed. Do not rely on what it says.': 'موقَّعة من {name}، لكن الرسالة تغيرت منذ توقيعها. لا تعتمد على ما تقوله.',
  'Signed by {name}, but the message names no sender to compare the certificate with.': 'موقّعة من {name}، لكن الرسالة لا تذكر مرسلًا لمقارنة الشهادة به.',
  'Signed by {name}, who is not the sender: the certificate is for {email}, and the message says it is from {from}.': 'موقّعة من {name}، وهو ليس المرسل: الشهادة لـ {email}، والرسالة تقول إنها من {from}.',
  'Signed by {name}. The signature is valid and the message has not changed since it was signed.': 'موقَّعة من {name}. التوقيع صالح ولم تتغير الرسالة منذ توقيعها.',
