  'That file no longer exists.': 'لم يعد هذا الملف موجودًا.',
  'That formula does not produce a number': 'لا تُنتج هذه الصيغة رقمًا',
  'That is more cells than a script may set at once': 'هذا عدد من الخلايا أكبر مما يمكن للبرنامج النصي تعيينه دفعة واحدة',
  'That is not a 3D model': 'هذا ليس نموذجًا ثلاثي الأبعاد',
