  'There are no other windows.': 'لا توجد نوافذ أخرى.',
  'There are no rows of data to subtotal': 'لا توجد صفوف بيانات لحساب إجماليات فرعية لها',
  'There are no slides to zoom to.': 'لا توجد شرائح يمكن التكبير إليها.',
  'There is already a column "{to}"': 'يوجد عمود باسم «{to}» بالفعل',
  'There is already a custom show called "{name}".': 'يوجد عرض مخصص باسم «{name}» بالفعل.',
