  'There is no column "{name}"': 'لا يوجد عمود باسم «{name}»',
  'There is no comment on this cell to delete.': 'لا يوجد تعليق في هذه الخلية لحذفه.',
  'There is no ink on this slide to replay.': 'لا يوجد حبر على هذه الشريحة لإعادة تشغيله.',
  'There is no invitation to answer.': 'لا توجد دعوة للرد عليها.',
  'There is no other table or query in this workbook to append.': 'لا يوجد جدول أو استعلام آخر في هذا المصنف لإلحاقه.',
  'There is no other table or query in this workbook to merge with.': 'لا يوجد جدول أو استعلام آخر في هذا المصنف للدمج معه.',
  'There is no paragraph style "{style}" to link a level to.': 'لا يوجد نمط فقرة باسم «{style}» لربط مستوى به.',
