  'This is the first time this deck has been open on this computer, so there is nothing to compare it with yet. Next time, whatever is new in the file is listed here.': 'هذه هي المرة الأولى التي يُفتح فيها هذا العرض التقديمي على هذا الكمبيوتر، لذا لا يوجد ما تتم مقارنته به بعد. في المرة القادمة، سيُدرج هنا كل ما هو جديد في الملف.',
  'This is the latest release.': 'هذا هو أحدث إصدار.',
  'This is the list of recipients that will be used in your merge. Use the checkboxes to add or remove recipients; click a column heading to sort by it.': 'هذه قائمة المستلمين التي سيتم استخدامها في الدمج. استخدم خانات الاختيار لإضافة مستلمين أو إزالتهم؛ وانقر فوق عنوان عمود للفرز حسبه.',
  'This is the only window to arrange.': 'هذه هي النافذة الوحيدة المتاحة للترتيب.',
  'This letter takes its recipients from {name}. Attach the list?': 'تأخذ هذه الرسالة مستلميها من {name}. هل تريد إرفاق القائمة؟',
  'This letter\'s recipient list is on a network share ({path}), so it is not opened from the letter. Select Recipients → Use an Existing List to choose it.': 'قائمة مستلمي هذه الرسالة موجودة على مجلد مشترك على الشبكة ({path})، لذا لا يتم فتحها من الرسالة. اختر تحديد المستلمين ← استخدام قائمة موجودة لاختيارها.',
  'This list has no subtotals to remove': 'لا تحتوي هذه القائمة على إجماليات فرعية لإزالتها',
  'This message is encrypted in a way this cannot open yet.': 'هذه الرسالة مشفَّرة بطريقة لا يمكن فتحها بعد.',
  'This message is encrypted, and no certificate on this computer opens it. Import yours (a .p12 or .pfx file) to read it.': 'هذه الرسالة مشفَّرة، ولا توجد على هذا الحاسوب شهادة تفتحها. استورد شهادتك (ملف .p12 أو .pfx) لقراءتها.',
  'This message is encrypted, but it is damaged and cannot be opened.': 'هذه الرسالة مشفَّرة، لكنها تالفة ولا يمكن فتحها.',
  'This message is in Junk because {reason}.': 'هذه الرسالة في البريد غير الهام لأن {reason}.',
  'This message is in Junk.': 'هذه الرسالة في البريد غير الهام.',
  'This message is signed in a way this cannot check yet.': 'هذه الرسالة موقَّعة بطريقة لا يمكن التحقق منها بعد.',
  'This message is signed, but the signer\'s certificate is neither in it nor on this computer, so the signature cannot be checked.': 'هذه الرسالة موقَّعة، لكن شهادة الموقِّع ليست فيها ولا على هذا الحاسوب، لذا لا يمكن التحقق من التوقيع.',
  'This message is too large to check its signature or encryption.': 'هذه الرسالة أكبر من أن يُتحقق من توقيعها أو تشفيرها.',
  'This message\'s signature or encryption could not be read.': 'تعذّرت قراءة توقيع هذه الرسالة أو تشفيرها.',
  'This modification is not allowed because the selection is locked.': 'هذا التعديل غير مسموح به لأن التحديد مؤمّن.',
  'This object is kept in the deck, but nothing here opens it.': 'يُحتفظ بهذا الكائن في العرض التقديمي، لكن لا يوجد هنا ما يمكنه فتحه.',
  'This object is kept in the document, but nothing here opens it.': 'يُحتفظ بهذا الكائن في المستند، لكن لا يوجد هنا ما يمكنه فتحه.',
  'This opens {host} in your browser, where the sender handles it.': 'يؤدي هذا إلى فتح {host} في المستعرض، حيث يتولى المرسل معالجة الطلب.',
  'This photo keeps its turn where it cannot be changed without redrawing it. Edit opens it in Image, which can.': 'دوران هذه الصورة محفوظ بطريقة لا يمكن تغييرها دون إعادة رسمها. يفتحها الأمر «تحرير» في محرر الصور، الذي يستطيع ذلك.',
