  'This picture is animated': 'هذه الصورة متحركة',
  'This places a picture of your signature on the page. It is not a digital signature: it does not prove who signed the PDF, or that the PDF has not been changed since.': 'يضع هذا صورة لتوقيعك على الصفحة. وهو ليس توقيعًا رقميًا: لا يثبت من وقّع ملف PDF، ولا أن الملف لم يتغير منذ ذلك.',
