  'A table was longer than a sheet can hold, so its first 1,048,575 rows are here.': { zero: 'لا جداول أطول مما تتسع له الورقة.', one: 'كان جدول أطول مما تتسع له الورقة، فهنا أول 1,048,575 صفًا منه.', two: 'كان جدولان أطول مما تتسع له الورقة، فهنا أول 1,048,575 صفًا من كل منهما.', few: 'كانت {count} جداول أطول مما تتسع له الورقة، فهنا أول 1,048,575 صفًا من كل منها.', many: 'كان {count} جدولاً أطول مما تتسع له الورقة، فهنا أول 1,048,575 صفًا من كل منها.', other: 'كان {count} جدول أطول مما تتسع له الورقة، فهنا أول 1,048,575 صفًا من كل منها.' },
  'Its formula is kept as the value 1-2-3 last worked out.': { zero: 'لا صيغ فيه.', one: 'صيغته محفوظة بالقيمة التي حسبها 1-2-3 آخر مرة.', two: 'صيغتاه محفوظتان بالقيمتين اللتين حسبهما 1-2-3 آخر مرة.', few: 'صيغه الـ{count} محفوظة بالقيم التي حسبها 1-2-3 آخر مرة.', many: 'صيغه الـ{count} محفوظة بالقيم التي حسبها 1-2-3 آخر مرة.', other: 'صيغه الـ{count} محفوظة بالقيم التي حسبها 1-2-3 آخر مرة.' },
