  '{count} formula was kept as its value: it uses {uses}, which the spreadsheet has no word for.': { zero: 'لم تُحفظ أي صيغة بقيمتها بسبب {uses}.', one: 'حُفظت صيغة واحدة بقيمتها: فهي تستخدم {uses}، وليس له مقابل في جدول البيانات.', two: 'حُفظت صيغتان بقيمتيهما: فهما تستخدمان {uses}، وليس له مقابل في جدول البيانات.', few: 'حُفظت {count} صيغ بقيمها: فهي تستخدم {uses}، وليس له مقابل في جدول البيانات.', many: 'حُفظت {count} صيغة بقيمها: فهي تستخدم {uses}، وليس له مقابل في جدول البيانات.', other: 'حُفظت {count} صيغة بقيمها: فهي تستخدم {uses}، وليس له مقابل في جدول البيانات.' },
