  'Update the design': 'تحديث التصميم',
  'A newer design of this database is ready: {count} change to its tables, queries, forms, reports or print templates. Your records stay as they are, and anything you changed keeps your version.': { zero: 'تصميم أحدث لقاعدة البيانات هذه جاهز، بلا تغييرات.', one: 'تصميم أحدث لقاعدة البيانات هذه جاهز: تغيير واحد في جداولها أو استعلاماتها أو نماذجها أو تقاريرها أو قوالب طباعتها. تبقى سجلاتك كما هي، وما غيّرته يبقى بنسختك.', two: 'تصميم أحدث لقاعدة البيانات هذه جاهز: تغييران في جداولها أو استعلاماتها أو نماذجها أو تقاريرها أو قوالب طباعتها. تبقى سجلاتك كما هي، وما غيّرته يبقى بنسختك.', few: 'تصميم أحدث لقاعدة البيانات هذه جاهز: {count} تغييرات في جداولها أو استعلاماتها أو نماذجها أو تقاريرها أو قوالب طباعتها. تبقى سجلاتك كما هي، وما غيّرته يبقى بنسختك.', many: 'تصميم أحدث لقاعدة البيانات هذه جاهز: {count} تغييرًا في جداولها أو استعلاماتها أو نماذجها أو تقاريرها أو قوالب طباعتها. تبقى سجلاتك كما هي، وما غيّرته يبقى بنسختك.', other: 'تصميم أحدث لقاعدة البيانات هذه جاهز: {count} تغيير في جداولها أو استعلاماتها أو نماذجها أو تقاريرها أو قوالب طباعتها. تبقى سجلاتك كما هي، وما غيّرته يبقى بنسختك.' },
  'The design is up to date: {count} change, your records as they were.': { zero: 'التصميم محدّث بلا تغييرات، وسجلاتك كما كانت.', one: 'التصميم محدّث: تغيير واحد، وسجلاتك كما كانت.', two: 'التصميم محدّث: تغييران، وسجلاتك كما كانت.', few: 'التصميم محدّث: {count} تغييرات، وسجلاتك كما كانت.', many: 'التصميم محدّث: {count} تغييرًا، وسجلاتك كما كانت.', other: 'التصميم محدّث: {count} تغيير، وسجلاتك كما كانت.' },
  'The design is up to date: {count} change. Where you had changed something, your version is kept and the newer one is beside it, named (updated).': { zero: 'التصميم محدّث بلا تغييرات.', one: 'التصميم محدّث: تغيير واحد. حيث غيّرت شيئًا بقيت نسختك، والأحدث بجانبها باسم (updated).', two: 'التصميم محدّث: تغييران. حيث غيّرت شيئًا بقيت نسختك، والأحدث بجانبها باسم (updated).', few: 'التصميم محدّث: {count} تغييرات. حيث غيّرت شيئًا بقيت نسختك، والأحدث بجانبها باسم (updated).', many: 'التصميم محدّث: {count} تغييرًا. حيث غيّرت شيئًا بقيت نسختك، والأحدث بجانبها باسم (updated).', other: 'التصميم محدّث: {count} تغيير. حيث غيّرت شيئًا بقيت نسختك، والأحدث بجانبها باسم (updated).' },
